// src/pages/CreateArticlePage.js
import React, { useState, useEffect } from "react";
import { contentFactory } from "../services/contentFactory";

function CreateArticlePage() {
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");

  const [articleData, setArticleData] = useState({
    title: "",
    content: "",
    image: null,
    category: "sport",
  });

  const token = localStorage.getItem("token");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/channels/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) =>
        setChannels(Array.isArray(data) ? data : data.results || [])
      );
  }, [token]);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (files) {
      setArticleData({ ...articleData, [name]: files[0] });
    } else {
      setArticleData({ ...articleData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const create = contentFactory("article", token);

    const payload = {
      title: articleData.title,
      content: articleData.content,
      image: articleData.image,
      channel: selectedChannel ? selectedChannel : null,
      category: selectedChannel ? null : articleData.category,
    };

    await create(payload);
    alert("Стаття створена ✅");
  };

  return (
    <div style={{ maxWidth: 600, margin: "auto" }}>
      <h2>Створення статті</h2>

      <form onSubmit={handleSubmit}>
        <input
          name="title"
          placeholder="Заголовок"
          value={articleData.title}
          onChange={handleChange}
          required
        />

        <textarea
          name="content"
          placeholder="Текст"
          value={articleData.content}
          onChange={handleChange}
          rows="6"
          required
        />

        <label>Канал (опціонально):</label>
        <select
          value={selectedChannel}
          onChange={(e) => setSelectedChannel(e.target.value)}
        >
          <option value="">Без каналу</option>
          {channels.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>

        {!selectedChannel && (
          <>
            <label>Категорія:</label>
            <select
              name="category"
              value={articleData.category}
              onChange={handleChange}
            >
              <option value="sport">sport</option>
              <option value="news">news</option>
              <option value="fashion">fashion</option>
            </select>
          </>
        )}

        <input type="file" name="image" onChange={handleChange} />

        <button type="submit">Створити</button>
      </form>
    </div>
  );
}

export default CreateArticlePage;
